        begin: '(-?)(\\b0[xX][A-Fa-f0-9\\\']+|(\\b[\\d\\\']+(\\.[\\d\\\']*)?|\\.[\\d\\\']+)([eE][-+]?[\\d\\\']+)?)'
      }
=======
      {
        // include optional suffixes on both hex and scientific forms
        begin: '(-?)(\\b0[xX][A-Fa-f0-9\\\']+|(\\b[\\d\\\']+(\\.[\\d\\\']*)?|\\.[\\d\\\']+)([eE][-+]?[\\d\\\']+)?)(?:u|U|l|L|ul|UL|ll|LL|ull|ULL|llu|LLU)?'
